// ---- KN Layerworks runtime: the MACHINE-API mount(). Uses TURN (inlined above), KNL_MODEL, KNL_CSS, KNL_DATA.
const KNL_IDS = ["order", "design", "ams", "toolhead", "plate", "shop", "printer"];

export function mount(container, { theme = "dark", autoRotate = true, debug = false } = {}) {
  const D = KNL_DATA;
  const MODEL = KNL_MODEL;
  const W = D.W;
  const H = D.H;
  const reduced = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : { matches: false };
  const root = document.createElement("div");
  root.className = "iso knl";
  root.dataset.theme = theme === "light" ? "light" : "dark";
  root.tabIndex = 0;
  root.setAttribute("role", "img");
  root.setAttribute("aria-label", "KN Layerworks: a desktop 3D printer with a four-spool AMS on top, an order-ticket printer, a parametric design console and a dispatch box on a turntable. Drag or use the arrow keys to turn it; click or press Enter to take it apart.");
  const labelSvg = D.labels
    .map((l, i) => `<g class="knl-label" data-id="${l.id}" data-i="${i}"><rect class="knl-label-box" x="0" y="0" width="0" height="0" rx="2"/><text class="knl-label-text" x="0" y="0">${l.text}</text></g>`)
    .join("");
  root.innerHTML = `<style>${KNL_CSS}</style><div class="knl-stage iso-stage iso-turn"><svg class="iso-svg iso-layer knl-back" viewBox="0 0 ${W} ${H}" aria-hidden="true">${D.halo}</svg>${D.live}<svg class="iso-svg iso-layer knl-labels" viewBox="0 0 ${W} ${H}" aria-hidden="true">${labelSvg}</svg></div>`;
  container.appendChild(root);
  const stage = root.querySelector(".knl-stage");
  let external = false; // a test tool drove the controller through window.__isoTurn: stand still
  const controller = TURN.mount(stage, D.turn, { onHold: () => (external = true) });
  if (!debug && typeof window !== "undefined" && window.__isoTurn && window.__isoTurn.controller === controller) delete window.__isoTurn;

  // ---- part nodes
  const nodes = new Map();
  const nodeOf = (i) => {
    if (!nodes.has(i)) nodes.set(i, stage.querySelector(`.iso-live [data-p="${i}"]`));
    return nodes.get(i);
  };
  D.glass.forEach((i) => nodeOf(i)?.classList.add("knl-glass"));
  D.asm.forEach((id, i) => {
    const n = nodeOf(i);
    if (n) n.setAttribute("data-asm", id);
  });
  const opacityMemo = new Map();
  const setOpacity = (i, v) => {
    const q = Math.round(v * 64) / 64;
    if (opacityMemo.get(i) === q) return;
    opacityMemo.set(i, q);
    const n = nodeOf(i);
    if (!n) return;
    if (q >= 1) n.style.removeProperty("opacity");
    else n.style.opacity = String(q);
  };
  const labels = [...root.querySelectorAll(".knl-label")];
  for (const g of labels) {
    const t = g.querySelector("text");
    const r = g.querySelector("rect");
    try {
      const b = t.getBBox();
      const pad = 5;
      r.setAttribute("x", String(b.x - pad));
      r.setAttribute("y", String(b.y - pad + 0.5));
      r.setAttribute("width", String(b.width + 2 * pad));
      r.setAttribute("height", String(b.height + 2 * pad - 1));
    } catch {}
  }

  // ---- state
  let angle = -18;
  let vel = 0;
  let nudge = 0;
  let explodeP = 0;
  let explodeOn = false;
  let printW = reduced.matches ? 0 : 1;
  let printT = 3.2;
  const spools = [0, 0, 0, 0];
  let selected = null;
  let paused = false;
  let visible = true;
  let held = 0;
  let frame = 0;
  let last = 0;
  let fade = 1; // reduced-motion cross-fade
  let fadeTo = null;
  let drag = null;
  let ema = 6;
  let odd = false;
  let dirty = true;
  let lowPower = false; // set when frames cost too much (weak phones): idle motion stops, input still renders
  let costly = 0;
  const AUTO = 9; // deg/s: one turn in 40 s

  const fire = (type, detail) => container.dispatchEvent(new CustomEvent(type, { detail, bubbles: true }));
  const now = () => (typeof performance !== "undefined" ? performance.now() : Date.now());

  function applySelection() {
    root.toggleAttribute("data-selected", Boolean(selected));
    D.asm.forEach((id, i) => {
      const n = nodeOf(i);
      if (n) n.classList.toggle("knl-dim", Boolean(selected) && id !== selected);
    });
    for (const g of labels) g.classList.toggle("knl-on", g.dataset.id === selected);
  }

  function render() {
    const values = MODEL.follow({ spin: angle, explode: explodeP, print: printT, printing: printW, strokes: D.strokes, spool: spools });
    const t0 = now();
    controller.set(values);
    ema += (now() - t0 - ema) * 0.1;
    costly = ema > 40 ? costly + 1 : 0;
    if (costly > 12 && !lowPower) {
      lowPower = true;
      root.setAttribute("data-low-power", "");
    }
    // printing visibility
    const s = MODEL.printState(printT, D.strokes);
    const mix = (v) => 1 - (1 - v) * printW;
    D.fades.tag.forEach((i) => setOpacity(i, mix(s.tag)));
    D.fades.strokes.forEach((i, j) => setOpacity(i, mix(s.strokes[j])));
    D.fades.ticket.forEach((i) => setOpacity(i, mix(s.ticketFade)));
    // explode framing + labels
    const e = MODEL.smooth(explodeP);
    stage.style.transform = e > 0.0005 ? `translate3d(0, ${(3 * e).toFixed(3)}%, 0) scale(${(1 - 0.27 * e).toFixed(4)})` : "";
    const show = MODEL.smooth((explodeP - 0.55) / 0.45);
    root.style.setProperty("--knl-labels", show.toFixed(3));
    if (show > 0.001) {
      D.labels.forEach((l, i) => {
        const a = controller.anchor(l.group, l.at);
        labels[i].setAttribute("transform", `translate(${a.screen[0].toFixed(1)} ${(a.screen[1] - 8).toFixed(1)})`);
      });
    }
    dirty = false;
  }

  function tick(t) {
    frame = 0;
    if (external) return;
    const dt = last ? Math.min((t - last) / 1000, 1 / 20) : 1 / 60;
    last = t;
    const calm = reduced.matches;
    let moving = false;
    // spin
    if (!drag) {
      if (Math.abs(vel) > 0.5) {
        angle += vel * dt;
        vel *= Math.exp(-dt / 0.55);
        moving = true;
      } else vel = 0;
      if (Math.abs(nudge) > 0.01) {
        const step = nudge * (1 - Math.exp(-dt / 0.14));
        angle += step;
        nudge -= step;
        moving = true;
      } else nudge = 0;
      if (autoRotate && !calm && !lowPower && !explodeOn && explodeP === 0 && t > held) {
        angle += AUTO * dt;
        moving = true;
      }
    }
    // printing weight parks before the machine comes apart
    const wantPrint = !calm && !lowPower && !explodeOn && explodeP === 0 ? 1 : 0;
    const before = printW;
    printW += (wantPrint - printW) * (1 - Math.exp(-dt / (wantPrint ? 0.5 : 0.18)));
    if (Math.abs(printW - wantPrint) < 0.004) printW = wantPrint;
    if (printW !== before) moving = true;
    if (printW > 0) {
      printT = (printT + dt) % MODEL.LOOP;
      const st = MODEL.printState(printT, D.strokes);
      if (st.active >= 0) spools[st.active] += 70 * dt * printW;
      moving = true;
    }
    // explode
    if (calm) {
      if (fadeTo !== null) {
        fade = Math.max(0, fade - dt / 0.2);
        if (fade === 0) {
          explodeP = fadeTo;
          fadeTo = null;
        }
        moving = true;
      } else if (fade < 1) {
        fade = Math.min(1, fade + dt / 0.25);
        moving = true;
      }
      stage.style.opacity = fade < 1 ? String(fade) : "";
    } else {
      const target = explodeOn ? 1 : 0;
      if (explodeP !== target && (!explodeOn || printW === 0)) {
        const rate = dt / 1.5;
        explodeP = target > explodeP ? Math.min(target, explodeP + rate) : Math.max(target, explodeP - rate);
        moving = true;
      }
    }
    if (moving || dirty) {
      odd = !odd;
      // idle motion (9°/s turn, printing) is smooth at 30 fps; direct input gets every frame while the budget allows
      const direct = Boolean(drag) || vel !== 0 || nudge !== 0 || (explodeP !== 0 && explodeP !== 1) || fade < 1;
      if (dirty || odd || (direct && ema < 14)) render();
    }
    const more = moving || drag || (autoRotate && !calm && !lowPower && !explodeOn);
    if (more && !paused && visible) frame = requestAnimationFrame(tick);
  }
  const run = () => {
    if (!frame && !paused && visible) {
      last = 0;
      frame = requestAnimationFrame(tick);
    }
  };

  function explode(on) {
    on = Boolean(on);
    if (on === explodeOn) return;
    explodeOn = on;
    root.toggleAttribute("data-exploded", on);
    if (!on && selected) {
      selected = null;
      applySelection();
    }
    if (reduced.matches) fadeTo = on ? 1 : 0;
    fire("anatomy:explode", { on });
    dirty = true;
    run();
  }
  function select(id) {
    selected = id && KNL_IDS.includes(id) ? id : null;
    applySelection();
  }

  // ---- parts() / hover(): where each assembly is on screen, and a light highlight
  const liveSvg = stage.querySelector("svg.iso-live") || stage.querySelector(".iso-live")?.closest("svg") || null;
  const labelText = Object.fromEntries(D.labels.map((l) => [l.id, l.text.charAt(0) + l.text.slice(1).toLowerCase()]));
  let partIndex = null;
  function buildIndex() {
    const scene = controller.scene ? controller.scene() : null;
    const by = {};
    if (!scene) return by;
    const names = scene.groups.map((g) => g.name);
    scene.runs.forEach((r, i) => {
      const id = D.asm[i];
      if (!KNL_IDS.includes(id) || !r.centroid) return;
      // clouds are stored relative to their group origin; anchor() wants model coordinates
      const o = scene.groups[r.group]?.origin ?? [0, 0, 0];
      (by[id] ??= []).push([names[r.group] ?? null, [r.centroid[0] + o[0], r.centroid[1] + o[1], r.centroid[2] + o[2]]]);
    });
    return by;
  }
  function parts() {
    partIndex ??= buildIndex();
    const ctm = liveSvg && liveSvg.getScreenCTM ? liveSvg.getScreenCTM() : null;
    if (!ctm) return [];
    const box = container.getBoundingClientRect();
    const pt = liveSvg.createSVGPoint();
    return KNL_IDS.filter((id) => partIndex[id]).map((id) => {
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      for (const [g, c] of partIndex[id]) {
        const s = controller.anchor(g, c).screen;
        if (s[0] < x0) x0 = s[0];
        if (s[0] > x1) x1 = s[0];
        if (s[1] < y0) y0 = s[1];
        if (s[1] > y1) y1 = s[1];
      }
      pt.x = (x0 + x1) / 2;
      pt.y = (y0 + y1) / 2;
      const q = pt.matrixTransform(ctm);
      return { id, label: labelText[id] || id, x: q.x - box.left, y: q.y - box.top };
    });
  }
  let hovered = null;
  function hover(id) {
    id = id && KNL_IDS.includes(id) ? id : null;
    if (id === hovered) return;
    hovered = id;
    D.asm.forEach((a, i) => nodeOf(i)?.classList.toggle("knl-hov", a === id));
    for (const g of labels) g.classList.toggle("knl-hl", g.dataset.id === id);
    root.toggleAttribute("data-hover", Boolean(id));
    fire("anatomy:hover", { id });
  }
  // what is under the pointer, assembled or exploded (the live layer ignores the pointer otherwise)
  const asmUnder = (x, y) => {
    if (!liveSvg) return asmAt(x, y);
    const before = liveSvg.style.pointerEvents;
    liveSvg.style.pointerEvents = "auto";
    const id = asmAt(x, y);
    liveSvg.style.pointerEvents = before;
    return id;
  };

  // ---- input
  const hold = () => (held = now() + 2600);
  const asmAt = (x, y) => {
    const el = document.elementFromPoint(x, y);
    if (!el || !root.contains(el)) return null;
    const label = el.closest(".knl-label");
    if (label) return label.dataset.id;
    const part = el.closest("[data-asm]");
    const id = part ? part.getAttribute("data-asm") : null;
    return id && KNL_IDS.includes(id) ? id : null;
  };
  const onDown = (e) => {
    if (e.button !== undefined && e.button !== 0) return;
    hold();
    drag = { id: e.pointerId, x: e.clientX, y: e.clientY, lastX: e.clientX, lastT: now(), moved: false, v: 0 };
    vel = 0;
    run();
  };
  const onMove = (e) => {
    if (!drag && e.pointerType === "mouse") hover(asmUnder(e.clientX, e.clientY));
    if (!drag || e.pointerId !== drag.id) return;
    const dx = e.clientX - drag.lastX;
    if (!drag.moved && Math.hypot(e.clientX - drag.x, e.clientY - drag.y) > 5) {
      drag.moved = true;
      try {
        root.setPointerCapture(e.pointerId);
      } catch {}
      root.setAttribute("data-drag", "");
    }
    if (!drag.moved) return;
    const k = 360 / Math.max(320, root.clientWidth * 1.1);
    angle -= dx * k;
    const t = now();
    const dts = Math.max(0.001, (t - drag.lastT) / 1000);
    drag.v = drag.v * 0.6 + ((-dx * k) / dts) * 0.4;
    drag.lastX = e.clientX;
    drag.lastT = t;
    hold();
    dirty = true;
    run();
  };
  const onUp = (e) => {
    if (!drag || e.pointerId !== drag.id) return;
    const was = drag;
    drag = null;
    root.removeAttribute("data-drag");
    try {
      root.releasePointerCapture(e.pointerId);
    } catch {}
    hold();
    if (was.moved) {
      vel = Math.max(-400, Math.min(400, was.v));
      if (now() - was.lastT > 90) vel = 0;
    } else if (e.type === "pointerup") {
      if (!explodeOn) explode(true);
      else {
        const id = asmAt(e.clientX, e.clientY);
        if (id) {
          select(id);
          fire("anatomy:part", { id });
        } else explode(false);
      }
    }
    run();
  };
  const onKey = (e) => {
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      nudge += e.key === "ArrowLeft" ? 15 : -15;
      hold();
      run();
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      explode(!explodeOn);
    } else if (e.key === "Escape") {
      explode(false);
    } else if (explodeOn && /^[1-7]$/.test(e.key)) {
      const id = KNL_IDS[Number(e.key) - 1];
      select(id);
      fire("anatomy:part", { id });
    }
  };
  root.addEventListener("pointerdown", onDown);
  root.addEventListener("pointermove", onMove);
  root.addEventListener("pointerup", onUp);
  root.addEventListener("pointercancel", onUp);
  root.addEventListener("keydown", onKey);
  const onLeave = () => hover(null);
  root.addEventListener("pointerleave", onLeave);
  const io = typeof IntersectionObserver === "function"
    ? new IntersectionObserver((entries) => {
        visible = entries[entries.length - 1].isIntersecting;
        if (visible) run();
        else if (frame) {
          cancelAnimationFrame(frame);
          frame = 0;
        }
      }, { rootMargin: "80px" })
    : null;
  io?.observe(root);
  const onReduced = () => {
    if (reduced.matches) printW = 0;
    dirty = true;
    run();
  };
  reduced.addEventListener?.("change", onReduced);
  render();
  run();

  return {
    explode,
    select,
    parts,
    hover,
    setPaused(p) {
      paused = Boolean(p);
      if (paused && frame) {
        cancelAnimationFrame(frame);
        frame = 0;
      } else run();
    },
    setTheme(t) {
      root.dataset.theme = t === "light" ? "light" : "dark";
    },
    destroy() {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      io?.disconnect();
      reduced.removeEventListener?.("change", onReduced);
      root.removeEventListener("pointerdown", onDown);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerup", onUp);
      root.removeEventListener("pointercancel", onUp);
      root.removeEventListener("keydown", onKey);
      root.removeEventListener("pointerleave", onLeave);
      controller.destroy?.();
      root.remove();
    },
    // for stills and tests
    _state: () => ({ angle, explodeP, printT, printW, selected, ema, lowPower }),
    _set(o = {}) {
      if (o.angle !== undefined) angle = o.angle;
      if (o.print !== undefined) printT = o.print;
      if (o.explodeP !== undefined) explodeP = o.explodeP;
      dirty = true;
      render();
    },
  };
}
